using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Generic;using ZuneRestoration;
namespace EnhancedZune {
 public static class Slots { public static string LastFailure;
  public static void Export(string file,string folder){Hashtable all=BackgroundResources.ReadAll(file);string[] states=BackgroundResources.States(all);for(int i=0;i<3;i++)if(states[i].Length==64){string p=Path.Combine(folder,"CustomBackground"+(i+1)+".png");byte[] image=(byte[])all[BackgroundResources.Key(BackgroundResources.Name(i))];if(File.Exists(p)&&Engine.FileHash(p)!=Engine.Hash(image))p=Path.Combine(folder,"CustomBackground"+(i+1)+"-"+Engine.Hash(image)+".png");if(!File.Exists(p))File.WriteAllBytes(p,image);}}
  public static bool ValidEnhanced(string file,Manifest m){try{byte[] raw=File.ReadAllBytes(file);if(raw.Length>134217728)return false;using(BinaryReader b=new BinaryReader(new MemoryStream(raw))){b.BaseStream.Position=60;int nt=b.ReadInt32();if(nt<64||nt>raw.Length-512)return false;b.BaseStream.Position=nt;if(b.ReadUInt32()!=0x4550)return false;b.BaseStream.Position=nt+6;int count=b.ReadUInt16();if(count>32)return false;b.BaseStream.Position=nt+20;int optional=b.ReadUInt16(),opt=nt+24;b.BaseStream.Position=opt;int magic=b.ReadUInt16();if(magic!=0x20b&&magic!=0x10b)return false;int directories=magic==0x20b?112:96;b.BaseStream.Position=opt+60;int size=b.ReadInt32();if(size<512||size>16384||size>raw.Length)return false;byte[] header=new byte[size];Array.Copy(raw,header,size);foreach(int p in new[]{nt+8,opt+8,opt+56,opt+64,opt+directories+20,opt+directories+32,opt+directories+36})Array.Clear(header,p,4);int seen=0;for(int i=0;i<count;i++){int at=opt+optional+40*i;b.BaseStream.Position=at;string name=Encoding.ASCII.GetString(b.ReadBytes(8)).TrimEnd('\0');b.BaseStream.Position=at+16;int n=b.ReadInt32(),start=b.ReadInt32();if(n<0||start<0||(long)start+n>raw.Length)return false;if(name==".rsrc"){Array.Clear(header,at+8,4);Array.Clear(header,at+16,4);}else{string expected;if(!m.shell_sections.TryGetValue(name,out expected))return false;byte[] data=new byte[n];Array.Copy(raw,start,data,0,n);if(Engine.Hash(data)!=expected)return false;seen++;}}if(seen!=m.shell_sections.Count)throw new Exception("Section count mismatch.");if(Engine.Hash(header)!=m.shell_header)throw new Exception("Normalized PE header mismatch: "+Engine.Hash(header)+" expected "+m.shell_header);}
   Hashtable all=BackgroundResources.ReadAll(file);if(all.Count!=m.shell_resources.Count+4)throw new Exception("Resource count mismatch: "+all.Count+" vs "+m.shell_resources.Count);foreach(KeyValuePair<string,string> e in m.shell_resources){byte[] v=all[e.Key] as byte[];if(v==null||Engine.Hash(v)!=e.Value)throw new Exception("Resource mismatch: "+e.Key);}BackgroundResources.States(all);for(int i=0;i<3;i++)BackgroundResources.ValidatePng((byte[])all[BackgroundResources.Key(BackgroundResources.Name(i))]);return true;
  }catch(Exception error){LastFailure=error.ToString();return false;}}
 }
}
